# Error message constants
AGENT_NOT_READY_ERROR = "Agent not ready"
INVALID_REQUEST_ERROR = "Invalid request"

structlogger = structlog.get_logger()

# Create the blueprint
bp = Blueprint("bot_builder", url_prefix="/api")

# Documents the header every route that operates on an agent workspace requires.
_AGENT_ID_HEADER = openapi.parameter(
    HEADER_AGENT_ID,
    description=(
        "Id of the agent whose workspace the request operates on. Required: a "
        "missing or invalid id is answered with a 400."
    ),
    _in="header",
    required=True,
    schema=str,
)


def _is_localhost_request(request: Request) -> bool:
    """Check if the request originates from localhost.

    Args:
        request: The incoming request

    Returns:
        True if the request is from localhost, False otherwise
    """
    # Check the actual client IP
    client_ip = request.ip
    localhost_ips = {"127.0.0.1", "::1", "localhost"}
    return client_ip in localhost_ips


# Exception handlers stay synchronous: sanic-cors can't add CORS headers to
# an async handler's response, and a browser can't read an error without them.
@bp.exception(InvalidAgentIdError)
def handle_invalid_agent_id(request: Request, exc: InvalidAgentIdError) -> HTTPResponse:
    """Reject a request that names no valid agent with a 400."""
    return response.json(
        ApiErrorResponse(
            error=INVALID_REQUEST_ERROR,
            details={"header": HEADER_AGENT_ID, "message": str(exc)},
        ).model_dump(),
        status=HTTPStatus.BAD_REQUEST,
    )


@bp.exception(InvalidBranchNameError)
def handle_invalid_branch_name(
    request: Request, exc: InvalidBranchNameError
) -> HTTPResponse:
    """Reject a request that names an invalid branch with a 400."""
    return response.json(
        ApiErrorResponse(
            error=INVALID_REQUEST_ERROR,
            details={"header": HEADER_BRANCH, "message": str(exc)},
        ).model_dump(),
        status=HTTPStatus.BAD_REQUEST,
    )


@bp.exception(BranchNotFoundError)
def handle_branch_not_found(request: Request, exc: BranchNotFoundError) -> HTTPResponse:
    """Reject a request that names a branch the agent does not have."""
    return response.json(
        ApiErrorResponse(
            error="Branch not found", details={"message": str(exc)}
        ).model_dump(),
        status=HTTPStatus.NOT_FOUND,
    )


@bp.exception(AgentHasBranchesError)
def handle_agent_has_branches(
    request: Request, exc: AgentHasBranchesError
) -> HTTPResponse:
    """Refuse to start an agent over while it has branches besides `main`."""
    return response.json(
        ApiErrorResponse(
            error=str(exc),
            details={"code": "agent_has_branches", "branches": exc.branches},
        ).model_dump(),
        status=HTTPStatus.CONFLICT,
    )


def get_project_generator(request: Request) -> ProjectGenerator:
    """Return the generator of the agent named by the `X-Agent-Id` header.

    Route handlers call this outside their catch-all `except Exception` blocks,
    so that `InvalidAgentIdError` reaches `handle_invalid_agent_id` as a 400
    instead of being reported as a 500.

    Raises:
        InvalidAgentIdError: If the header is missing or not a valid id.
    """
    return resolve_workspace(request).project_generator


async def get_project_generator_to_start_over(request: Request) -> ProjectGenerator:
    """Return the generator of the agent's `main`, for a route that starts it over.

    Starting over replaces the agent's files and repository, so it ignores the
    `X-Branch` header and is refused while the agent has other branches.

    Raises:
        InvalidAgentIdError: If the header is missing or not a valid id.
        AgentHasBranchesError: If the agent has branches besides `main`.
    """
    main = resolve_main_workspace(request)
    if branches := await branches_besides_main(main):
        raise AgentHasBranchesError(branches)
    return main.project_generator


def get_agent_id(request: Request) -> str:
    """Return the id of the agent named by the `X-Agent-Id` header.

    Raises:
        InvalidAgentIdError: If the header is missing or not a valid id.
    """
    return resolve_main_workspace(request).agent_id


def get_input_channel(request: Request) -> InspectorInputChannel:
    """Get the input channel from app context."""
    return request.app.ctx.input_channel


async def extract_bot_data_from_agent(agent: Agent) -> BotData:
    """Extract BotData from an Agent.

    Args:
        agent: The agent to extract data from

    Returns:
        BotData containing flows, domain, config, endpoints, and nlu data
    """
    domain = agent.domain.as_dict() if agent.domain else {}
    flows = (
        await agent.processor.get_flows()
        if agent.processor
        else FlowsList(underlying_flows=[])
    )
    return BotData(
        flows=get_flows_as_json(flows),
        domain=extract_values(domain, DOMAIN_KEYS),
    )


async def get_agent_status(request: Request) -> AgentStatus:
    """Get the status of the agent."""
    if request.app.ctx.agent is None:
        return AgentStatus.not_loaded
    agent: Agent = request.app.ctx.agent
    if agent.is_ready():
        return AgentStatus.ready
    return AgentStatus.not_ready


