@bp.route("/tools", methods=["GET"])
@openapi.summary("Get agent tools")
@openapi.description(
    "Imports the agent's `@tool` modules the way `rasa train` does and lists "
    "the tools they define, plus every tool file that fails to load. Tools come "
    "from `skills/<skill_id>/tools.py`, `skills/<skill_id>/tools/*.py`, and the "
    "shared agent-root `tools/*.py`. A file in `errors` (an import error, a "
    "syntax error, or a reserved framework tool name) fails `rasa train` even "
    "when no skill uses its tools. Broken files are reported with status 200; "
    "`path` values match the keys of `GET /api/files`."
)
@openapi.tag("bot-files")
@_AGENT_ID_HEADER
@openapi.response(
    200,
    {"application/json": model_to_schema(ToolsResponse)},
    description="Tools and tool loading errors retrieved successfully",
)
@openapi.response(
    500,
    {"application/json": model_to_schema(ApiErrorResponse)},
    description="Internal server error",
)
@openapi.parameter(
    HEADER_USER_ID,
    description=(
        "Optional user id to associate requests (e.g., for telemetry/guardrails)."
    ),
    _in="header",
    required=False,
    schema=str,
)
async def get_tools(request: Request) -> HTTPResponse:
    """Get the agent's tools and the tool files that fail to load."""
    project_generator = get_project_generator(request)
    try:
        inventory = await asyncio.to_thread(
            inspect_tools, project_generator.project_folder
        )
        tools_response = ToolsResponse(
            tools=[
                ToolInfo(
                    name=tool.name,
                    description=tool.description,
                    path=tool.path,
                    skill_id=tool.skill_id,
                )
                for tool in inventory.tools
            ],
            errors=[
                ToolLoadError(path=error.path, message=error.message)
                for error in inventory.errors
            ],
        )
        return response.json(tools_response.model_dump())
    except Exception as exc:
        capture_exception_with_context(
            exc,
            "bot_builder_service.get_tools.unexpected_error",
            tags={"endpoint": "/api/tools", "method": "GET"},
        )
        return response.json(
            ApiErrorResponse(
                error="Failed to retrieve tools", details={"error": str(exc)}
            ).model_dump(),
            status=HTTPStatus.INTERNAL_SERVER_ERROR,
        )


