async def copilot_v2_models(request: Request) -> HTTPResponse:
    """Return the Copilot v2 model-picker menu."""
    # Import locally: the pydantic-ai extra is optional, so keep it out of
    # this module's import-time dependencies (mirrors the SSE endpoint).
