@bp.route("/agent-plans/<plan_id>/refine", methods=["POST"])
@openapi.summary("Refine an agent build plan with feedback")
@openapi.description(
    "Runs the planner again with user feedback against the existing plan's "
    "conversation, and persists the result as a new revision."
)
@openapi.tag("agent-plan")
@_AGENT_ID_HEADER
async def refine_agent_plan(request: Request, plan_id: str) -> HTTPResponse:
    """Refine a draft plan with feedback, adding a new planner revision."""
    try:
        from rasa.builder.agent_plan.planner import refine_plan
    except ImportError:
        return response.json({"error": "copilot_v2_not_installed"}, status=503)

    store = _get_agent_plan_store(request)
    record = await _get_agent_plan(request, plan_id)
    if record is None:
        return response.json({"error": "not_found"}, status=404)
    if record.status != PlanStatus.DRAFT:
        return response.json(
            {
                "error": "invalid_status",
                "message": f"Plan is {record.status.value}, not draft.",
            },
            status=409,
        )

    payload: Any = request.json if request.json is not None else {}
    feedback = payload.get("feedback") if isinstance(payload, dict) else None
    if not feedback or not isinstance(feedback, str):
        return response.json(
            {"error": "invalid_request", "message": "`feedback` is required."},
            status=422,
        )

    messages_json = await store.get_messages(plan_id)
    plan, new_messages_json = await refine_plan(
        feedback, messages_json, record.latest_revision.plan
    )
    try:
        updated = await store.add_revision(plan_id, plan, source="planner")
    except InvalidPlanTransitionError:
        # The plan was approved while the LLM call above was in flight; don't
        # overwrite the message history for a refine that never landed.
        return response.json(
            {"error": "invalid_status", "message": "Plan is no longer a draft."},
            status=409,
        )
    await store.set_messages(plan_id, new_messages_json)
    return response.json(_agent_plan_response(updated))


@bp.route("/agent-plans/<plan_id>", methods=["PATCH"])
@openapi.summary("Directly edit an agent build plan")
@openapi.description(
    "Validates the given plan body and persists it as a new, user-sourced "
    "revision. Does not touch the planner conversation history."
)
@openapi.tag("agent-plan")
@_AGENT_ID_HEADER
async def update_agent_plan(request: Request, plan_id: str) -> HTTPResponse:
    """Persist a direct user edit of the plan as a new revision."""
    store = _get_agent_plan_store(request)
    record = await _get_agent_plan(request, plan_id)
    if record is None:
        return response.json({"error": "not_found"}, status=404)
    if record.status != PlanStatus.DRAFT:
        return response.json(
            {
                "error": "invalid_status",
                "message": f"Plan is {record.status.value}, not draft.",
            },
            status=409,
        )

    payload: Any = request.json if request.json is not None else {}
    plan_payload = payload.get("plan") if isinstance(payload, dict) else None
    try:
        plan = AgentBuildPlan.model_validate(plan_payload)
    except ValidationError as exc:
        return response.json({"error": "invalid_plan", "message": str(exc)}, status=422)

    try:
        updated = await store.add_revision(plan_id, plan, source="user")
    except InvalidPlanTransitionError:
        return response.json(
            {"error": "invalid_status", "message": "Plan is no longer a draft."},
            status=409,
        )
    return response.json(_agent_plan_response(updated))


@bp.route("/agent-plans/<plan_id>", methods=["DELETE"])
@openapi.summary("Discard an agent build plan")
@openapi.description("Marks the plan as discarded. Refused once building/built.")
@openapi.tag("agent-plan")
@_AGENT_ID_HEADER
async def delete_agent_plan(request: Request, plan_id: str) -> HTTPResponse:
    """Discard a plan, refusing once it is building or built."""
    store = _get_agent_plan_store(request)
    record = await _get_agent_plan(request, plan_id)
    if record is None or record.status == PlanStatus.DISCARDED:
        return response.json({"error": "not_found"}, status=404)

    try:
        await store.set_status(plan_id, PlanStatus.DISCARDED)
    except InvalidPlanTransitionError:
        return response.json(
            {
                "error": "invalid_status",
                "message": f"Plan is {record.status.value}; cannot discard.",
            },
            status=409,
        )
    return HTTPResponse(status=204)


@bp.route("/agent-plans/<plan_id>/approve", methods=["POST"])
@openapi.summary("Approve an agent build plan and start building it")
@openapi.description(
    "Approves a draft plan and enqueues a background job that scaffolds a "
    "Mantle project and implements the plan. Optimistic concurrency: an "
    "optional `revision` in the body must match the plan's latest revision."
)
@openapi.tag("agent-plan")
@_AGENT_ID_HEADER
@openapi.response(
    400,
    {"application/json": {str: Any}},
    description=(
        "Invalid `thread_id`, or a `thread_id` was given without an `X-User-Id` "
        "header (`details.code` is `missing_user_id`)."
    ),
)
@openapi.response(
    404,
    {"application/json": {str: Any}},
    description="Unknown plan, or the given `thread_id` belongs to another user.",
)
@openapi.parameter(
    HEADER_USER_ID,
    description="User id owning `thread_id` (X-User-Id). Required with `thread_id`.",
    _in="header",
    required=False,
    schema=str,
)
async def approve_agent_plan(request: Request, plan_id: str) -> HTTPResponse:
    """Approve a draft plan and enqueue the build job.

    Mirrors the `/prompt-to-bot` job-creation pattern: allocate a job id via
    the shared `job_manager` and schedule the background task via
    `app.add_task`, returning the job id immediately. The build is pinned to
    the revision the caller approved (the latest revision, unless the caller
    passed an explicit `revision`), so it survives any later revision added
    to the plan before the job actually runs.
    """
    project_generator = await get_project_generator_to_start_over(request)
    store = _get_agent_plan_store(request)
    record = await _get_agent_plan(request, plan_id)
    if record is None:
        return response.json({"error": "not_found"}, status=404)
    if record.status != PlanStatus.DRAFT:
        return response.json(
            {
                "error": "invalid_status",
                "message": f"Plan is {record.status.value}, not draft.",
            },
            status=409,
        )

    payload: Any = request.json if request.json is not None else {}
    requested_revision = payload.get("revision") if isinstance(payload, dict) else None
    if (
        requested_revision is not None
        and requested_revision != record.latest_revision.revision
    ):
        return response.json(
            {
                "error": "stale_revision",
                "message": (
                    f"Plan is at revision {record.latest_revision.revision}, "
                    f"not {requested_revision}."
                ),
            },
            status=409,
        )
    approved_revision = (
        requested_revision
        if requested_revision is not None
        else record.latest_revision.revision
    )

    thread_id = payload.get("thread_id") if isinstance(payload, dict) else None
    if thread_id is not None:
        if not isinstance(thread_id, str):
            return response.json(
                {
                    "error": "invalid_request",
                    "message": "`thread_id` must be a string.",
                },
                status=400,
            )
        thread_id = thread_id.strip()
        if not thread_id or len(thread_id) > 200:
            return response.json(
                {
                    "error": "invalid_request",
                    "message": (
                        "`thread_id` must be non-empty and at most 200 " "characters."
                    ),
                },
                status=400,
            )
        caller_id = _copilot_v2_caller_id(request)
        if caller_id is None:
            return _missing_user_id_response()
        if not await _claim_copilot_v2_thread(request, thread_id, caller_id):
            return _thread_not_found_response()

    try:
        await store.set_status(plan_id, PlanStatus.APPROVED)
    except InvalidPlanTransitionError:
        return response.json(
            {"error": "invalid_status", "message": "Plan is no longer a draft."},
            status=409,
        )

    job = job_manager.create_job()
    await store.set_job_id(plan_id, job.id)

    request.app.add_task(
        run_plan_to_bot_job(
            request.app,
            project_generator,
            plan_id,
            approved_revision,
            thread_id=thread_id,
        )
    )

    return response.json({"planId": plan_id, "jobId": job.id}, status=202)


