@bp.route("/branches", methods=["POST"])
@openapi.summary("Create a branch of the agent")
@openapi.description(
    "Creates a branch from the head of `main`, or from `from_ref` (a branch "
    "name or commit SHA). The branch gets a checkout the first time a request "
    "names it in the `X-Branch` header."
)
@openapi.tag("git")
@_AGENT_ID_HEADER
@openapi.body(
    {"application/json": model_to_schema(CreateBranchRequest)},
    description="Name of the branch and where it starts.",
    required=True,
)
@openapi.response(
    201,
    {"application/json": model_to_schema(BranchListResponse)},
    description="Branch created; the response lists all branches",
)
@openapi.response(
    400,
    {"application/json": model_to_schema(ApiErrorResponse)},
    description="Invalid branch name",
)
@openapi.response(
    404,
    {"application/json": model_to_schema(ApiErrorResponse)},
    description="`from_ref` names no branch or commit of the agent",
)
@openapi.response(
    409,
    {"application/json": model_to_schema(ApiErrorResponse)},
    description="The branch exists already, or another git operation is running",
)
async def handle_create_branch(request: Request) -> HTTPResponse:
    """Create a branch of the requesting agent."""
    main = resolve_main_workspace(request)
    try:
        payload = CreateBranchRequest(**(request.json or {}))
    except Exception as exc:
        return response.json(
            ApiErrorResponse(
                error=INVALID_REQUEST_ERROR, details={"message": str(exc)}
            ).model_dump(),
            status=HTTPStatus.BAD_REQUEST,
        )

    try:
        await create_branch(main, payload.name, payload.from_ref)
    except InvalidBranchNameError as exc:
        return response.json(
            ApiErrorResponse(
                error=INVALID_REQUEST_ERROR,
                details={"field": "name", "message": str(exc)},
            ).model_dump(),
            status=HTTPStatus.BAD_REQUEST,
        )
    except (BranchAlreadyExistsError, GitOperationInProgressError) as exc:
        return response.json(
            ApiErrorResponse(
                error="Could not create branch", details={"message": str(exc)}
            ).model_dump(),
            status=HTTPStatus.CONFLICT,
        )

    branches = await list_branches(main, request.app.ctx.workspace_manager.root)
    return response.json(
        BranchListResponse(branches=branches).model_dump(), status=HTTPStatus.CREATED
    )


