async def _get_sanitized_tracker_context(
    app: Any,
    session_id: Optional[str],
    user_id: Optional[str],
) -> Optional[TrackerContext]:
    """Load, trim, and guardrail-sanitize the tracker context for one session.

    Keyed on (app, session_id, user_id) — not session_id alone — because the
    guardrails call needs the hello-rasa user id. When no guardrails checker is
    configured the context passes through unsanitized (v1 parity). Missing or
    stale sessions degrade to ``None`` at every layer.

    Args:
        app: The Sanic app owning the agent / tracker store.
        session_id: The Inspector conversation session id, if any.
        user_id: The hello-rasa user id used by the guardrails check, or
            ``None`` when the request carried no usable ``X-User-Id`` header.

    Returns:
        The (sanitized) tracker context, or ``None`` when unavailable.
    """
    if not session_id:
        return None
    tracker = await current_tracker_from_input_channel(app, session_id)
    tracker_context = TrackerContext.from_tracker(
        tracker, max_turns=COPILOT_ASSISTANT_TRACKER_MAX_TURNS
    )
    if (
        tracker_context is not None
        and llm_service.guardrails_policy_checker is not None
    ):
        tracker_context = await llm_service.guardrails_policy_checker.check_assistant_chat_for_policy_violations(  # noqa: E501
            tracker_context=tracker_context,
            hello_rasa_user_id=user_id,
            hello_rasa_project_id=HELLO_RASA_PROJECT_ID,
            lakera_project_id=LAKERA_ASSISTANT_HISTORY_GUARDRAIL_PROJECT_ID,
        )
    return tracker_context
